parameters.jsCode:
const body = $json.body || $json;
const data = body.data || body;

const kurum = (data.kurum || data.provider || 'BEDAŞ / AYEDAŞ / İSKİ').toUpperCase();
const binaAdi = (data.binaAdi || data.building || 'Belirtilmemiş Tesis/Site').trim();
const aboneNo = (data.aboneNo || data.subscriberNo || 'TR-' + Math.floor(1000000 + Math.random()*9000000)).trim();
const sayaNo = (data.sayacNo || data.meterNo || 'MTR-' + Math.floor(10000 + Math.random()*90000)).trim();
const donem = (data.donem || data.period || new Date().toISOString().slice(0,7)).trim();
const sonOdeme = (data.sonOdeme || data.dueDate || new Date(Date.now() + 10*86400000).toISOString().slice(0,10)).trim();
const tutar = parseFloat(data.tutar || data.amount || 0);
const faturaTuru = (data.faturaTuru || data.type || 'Ortak Alan Elektrik / Hidrofor').trim();

const invoiceId = `ALOINV-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;

return [{
  json: {
    invoiceId,
    kurum,
    binaAdi,
    aboneNo,
    sayaNo,
    donem,
    sonOdeme,
    tutar: tutar.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
    rawAmount: tutar,
    faturaTuru,
    parsedAt: new Date().toISOString()
  }
}];
